import { test, beforeEach } from "node:test";
import assert from "node:assert/strict";
import { app } from "../src/api/routes.ts";
import { resetUsers } from "../src/auth/users.ts";
import { resetSessions } from "../src/auth/session.ts";

const call = (method: string, path: string, body?: unknown, token?: string) =>
  app({ method, path, body, headers: token ? { authorization: `Bearer ${token}` } : {} });

beforeEach(() => {
  resetUsers();
  resetSessions();
});

test("signup creates user and signs in, returns 201 with token and public user", async () => {
  const res = await call("POST", "/api/signup", { email: "test@example.com", name: "Test", password: "password123" });
  assert.equal(res.status, 201);
  const body = res.body as { token: string; user: { id: string; email: string; name: string } };
  assert.ok(body.token);
  assert.deepEqual(body.user, { id: body.user.id, email: "test@example.com", name: "Test" });
  const me = await call("GET", "/api/me", undefined, body.token);
  assert.deepEqual(me.body, body.user);
});

test("signup returns 400 on invalid email", async () => {
  const res = await call("POST", "/api/signup", { email: "bad", name: "T", password: "password123" });
  assert.equal(res.status, 400);
  assert.deepEqual(res.body, { error: "invalid email" });
});

test("signup returns 400 on short password", async () => {
  const res = await call("POST", "/api/signup", { email: "t@e.com", name: "T", password: "short" });
  assert.equal(res.status, 400);
  assert.deepEqual(res.body, { error: "password must be at least 8 characters" });
});

test("signup returns 400 on duplicate email", async () => {
  await call("POST", "/api/signup", { email: "t@e.com", name: "T1", password: "password123" });
  const res = await call("POST", "/api/signup", { email: "T@E.com", name: "T2", password: "password456" });
  assert.equal(res.status, 400);
  assert.deepEqual(res.body, { error: "email already registered" });
});

test("signup returns 400 on missing fields", async () => {
  const res = await call("POST", "/api/signup", { email: "t@e.com", name: "T" });
  assert.equal(res.status, 400);
  assert.ok("error" in (res.body as any));
});
